		const roles = await db
			.select({
				createdAt: role.createdAt,
				description: role.description,
				id: role.id,
				isSystem: role.isSystem,
				name: role.name,
				slug: role.slug,
				userCount: count(userRole.userId),
			})
			.from(role)
			.leftJoin(userRole, eq(userRole.roleId, role.id))
